        counts[key] = counts.get(key, 0) + 1
    return {"requirement_counts": [{"model": k[0], "gate": k[1], "status": k[2], "cnt": v} for k, v in sorted(counts.items())], "top_conflicts": conflicts()[:20], "data_gap_requirements": gaps_from(data)[:20]}

