        provider = Neo4jEvidenceProvider(_Driver(_Transaction([{
            "fact": {
                "id": "FACT-SURVEY", "kind": "survey_cell", "derivative": "G68",
                "region": "CN", "value": 8.1, "mapping_strength": "unmapped",
                "locator_json": '{"sheet":"CN_EU_2025","row":4,"column":2}',
